import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Ch_PcVtW.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART2/19.md","filePath":"ja-jp/Management2/PART2/19.md"}'),o={name:"ja-jp/Management2/PART2/19.md"};function n(S,a,s,i,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<p>► 2023/10</p><h2 id="日本のエンタメを更新したかった2度目の「bmsg-fes」" tabindex="-1">日本のエンタメを更新したかった2度目の「BMSG FES」 <a class="header-anchor" href="#日本のエンタメを更新したかった2度目の「bmsg-fes」" aria-label="Permalink to &quot;日本のエンタメを更新したかった2度目の「BMSG FES」&quot;">​</a></h2><p>#BMSGFES #変革 #ライブ演出</p><h3 id="「bmsgが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」" tabindex="-1">「BMSGが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」 <a class="header-anchor" href="#「bmsgが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」" aria-label="Permalink to &quot;「BMSGが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」&quot;">​</a></h3><p>「BMSG FES&#39;23」が2023年9月23日・24日に東京・東京体育館で、9月•30日10月1日に大阪・大阪城ホールで開催された。昨年の初開催では、BMSGの立ち上げからNovel Coreとの出会い、THE FIRST、BE:FIRSTの結成など、2年間の足跡を中心に物語を紡ぎ上げるようなフェスだった。2度目となる今回に新たに注力したのは何だったのか。改めてそのテーマから聞いた。</p><p>昨年のフェスは、まさにストーリーの回収のためのもの。そこまで応援してくれていた人ほど、強くストーリーを体感できるエモーショナルな良いものになったなと感じてくれたと思います。同様に、今年もストーリーの回収は最低限やらなくてはいけないものではありましたが、シンプルな回収以上に、BMSGが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたいと考えました。</p><p>日本で「エンタテインメント」という言葉を使うときには、どうしても派手な演出やフィクション性の強いもの、ファンタジーのようなものを強く意味しすぎているように思います。</p><p>要は、フィジカルが抜けている。本来、エンタテインメントって、もっとエンパワーメント的な要素も含めて、人々の暮らしを良くするためにあるもので、現実逃避のためのものではないと思うんです。そのために必要なのが、マンパワー。つまり、人間が輝いている瞬間を高いレベル、高いクオリティーで作ること。起業当時から、そこはすごく頑張ってきたことです。</p><p>具体的に言えば、ボーイズグループはニーズに合わせて作られたものを完璧に演じる人たちではなく、自由意志を持って表現したいものを突き詰める存在であるべきです。一方でソロアーティストにしても、全てにおいてナラティブ(語り手視点で語られる物語)が絶対に必要だと思います。だから、ストーリーの回収以上のものが不可欠でしたし、個々がナラティブを背負ったうえで、それをどう美しく映像に収めるか、その技術を更新していくかが、プレーヤーとスタッフが考えるべき今回の大きなテーマでした。</p><p>フェスをご覧になった方々から、スーパーボウル(アメリカンフットボールの最高峰の大会である、NFLの優勝決定戦)のハーフタイムショーみたいだ、と言われましたが、それを狙ったというよりは、結果として近いものになったというほうが正しいでしょう。スーパーボウルのハーフタイムショーは、あくまでも音楽が中心にある演出なので、音楽を鳴らすことを大事にしたBMSG FESも同じ方向性のものであることは確かです。日本のエンタテインメントはそこが抜け落ちがちなので、真新しく感じていただけた結果、スーパーボウルみたいだと思っていただけたのでしょうし、自分としてもやりがいを強く感じます。</p><h3 id="「映像」に挑戦し続ける理由" tabindex="-1">「映像」に挑戦し続ける理由 <a class="header-anchor" href="#「映像」に挑戦し続ける理由" aria-label="Permalink to &quot;「映像」に挑戦し続ける理由&quot;">​</a></h3><p><strong>前述のように、今回注力した1つが「映像」だ。BMSGが映像にプライオリティーを置いていることは、アーティストのMV(ミュージックビデオ)や「D.U.N.K.」などにも現れているが、「今後もクオリティーの進化を続けていかなくては」と語る。</strong></p><p>K-POPがなぜ世界中にファンがいるのかというと、その一翼を担っているのが映像のクオリティーの高さです。もっとも、海を越えて広げるために映像が不可欠だったから、クオリティーが独自の進化をしたとも言えるでしょう。日本でも(グローバルを目指すなら)当たり前のようにやらなくてはいけないことのような気がします。</p><p>今回のフェスで力を入れたのは、2つ。1つは、照明とかも含めて抜けたときの絵が面白いこと、もう1つはステージ上でのジンバル(動画撮影に使用する手ぶれ補正装置)撮影にこだわりました。「D.U.N.K.」ではドローン撮影をいろいろ試しましたし、今回も導入しましたが、今回、特に頑張ったのはジンバル撮影ですね。映画館や配信で見る人だけでなく、会場にいる人にとっても肉眼よりジンバル撮影のほうが臨場感があると思いますし、そうした映像のクオリティーが高ければ高いほど、最終的にはアーティスト自身の歌唱とかダンスとかのプリミティブな瞬間がより映えると思うんです。</p><p><strong>ステージの裏側から間近でアーティストそれぞれのパフォーマンスを見たが、歌いながらカメラマンとコミュニケーションを取っている様子も印象的だった。</strong></p><p>カメラクルーにやる気になってもらうことは大事ですね。そうでないと、こちら側のオーダーも多くなるし、修正も大変。実際に怒号や罵声が飛び交う現場も少なくないと聞きますが、そんなことをせず131に、楽しく忌憚なく意見交換できる空気作りは大事にしました。リハーサルで、勉強がてら来ていた若いカメラマンが入ったんですが、僕は結構気を使うほうなんで、相手の顔色をうかがいながらいろんなオーダーを出していたんです。そうしたら、「もっとくれ」みたいな顔をしていたので、ぐいぐいお願いして(笑)。リハ段階で何回か失敗もするんですが、「もう1回」とポジティブな空気感でできたうえに、すごくキラキラした目をしていたんですよ。そのまま本番の全公演、彼にお願いしました。</p><p>そうしたコミュニケーションが嫌な空気にならずにできるのは、自分の性格もありますが、BMSGが起業から数年の会社であること、アーティストも若い新人が多いっていうことなどもプラスに働いていると思います。あと、アーティスト本人も、いいものを作ることに対してみんな前向きで、自分は「大人の文化祭」という言葉をずっと大事にしているんですが、その空気でできていることも大きいと思います。自分のマネジメントが成功していると誇れる部分でもありますね。</p><p><strong>会場の天井からは、BMSGEASTチームの陣地であるステージ上手には大きな太陽、BMSGWESTチームの下手には月のモチーフが飾られていた。映像には皆既日食のようなモチーフも出てきた。EASTとWESTの2チーム制、それぞれの楽曲やMVなどに隠された裏テーマは何だったのか。</strong></p><p>見ている方には伝わらなくてもいいものですが、プロデュースにあたって設定したものはあります。太陽の国と月の国の2つの世界に住む人々がいるけれども、彼らは決して交わることがないままそれぞれに暮らしているんです。でも、60年に1度、月と太陽が同時に上る日があり、その時だけは両方の住民が邂逅し、大きなお祭りが開かれるんです。EASTとWESTのチームは、それぞれ太陽の国と月の国を代表して、コロッセオみたいな場所で開催される何かの対抗戦に出ているようなもの。戦う、というよりはJリーグやNBAのオールスター戦っぽいイベントですね。</p><p>こうした設定を、ライブを担当するチームとの打ち合わせで共有して、みんなに動いてもらいます。チームとしての経験が蓄積されてきたので、自分が関わらないと進まないことも減ってきましたし、今、本当に助かっています。</p><p>あと、強力なスタッフが最近クリエーティブディレクターとして正式にBMSGに加入したことも大きいです。前回のフェスの際、終演後の帰り道でもお客さんにライブの世界観を感じてほしくて、壁にプロジェクターでイメージ映像を映し出したり、提灯を掲げたりしたんですが、その手伝いをしてもらったところから関係が始まって、そのときは外注スタッフとしてお願いしたのですが、フェス後、「天啓がありました。僕はもっとBMSGにコミットしなくちゃいけないと思ったんですけど、何か手伝えることはありますか？」と言ってくれて。それで軽くお願いごとをしてみたら、「クリエーティブディレクターってこんなことができるのか！」が本当に多くて。クリエーティブに関して、自分のタッチ数が半分になって、自分のタッチポイントが2倍になった感覚があります。</p><p>今回の設定を太陽の国と月の国にしようと思ったのもそのスタッフとの会話の延長だし、僕が設定を話すと、「邂逅するのは何年に1回ですか？」「どんな祭りですか？」と質問してくれるからいろいろ具体的になるし、それを膨らませたアイデアを出してくれる。設定を話した翌日に軽いスケッチを出してくれるのも、イメージのすり合わせができるのでありがたいですね。</p><h3 id="_23年の手応えで来年以降に自信" tabindex="-1">23年の手応えで来年以降に自信 <a class="header-anchor" href="#_23年の手応えで来年以降に自信" aria-label="Permalink to &quot;23年の手応えで来年以降に自信&quot;">​</a></h3><p><strong>約5時間にも及んだライブだったが、あっという間に時間が過ぎた。シームレスなセットリストにもその理由がありそうだ。</strong></p><p>予定より長くなったのは、いざアーティストたちがステージに立つと、しゃべりたいことがたくさんあったようで。それはうれしいことですが、単純計算で23人全員が2分多く話すと46分延びるわけです(笑)。</p><p>セットリストを作るときに大事にしたのもナラティブであり、あとはシームレスであることでした。コアやShota(Aile The Shota)のパートはそれぞれにおまかせしながら、最初と最後だけは極力前後とシームレスにつながるように調整して。面白いコラボ曲がまだいっぱいあるので、こうしたシームレス性は、まだまだ進化してくんじゃないかな。</p><p><strong>気が早いかもしれないが、今年のBMSG FESの手応えを得た今、来年以降はどんな形にしようと考えているのだろうか。</strong></p><p>前回は、フェスを意識してそれまでの2年間を進めてきたこともあって、起業からそこまでのルートが正しければどう転んでもエモくなりますし、企画に2年間を費やして来られたわけです。でも、今回は思い描いていたストーリーを現実にするだけじゃなくて、現在進行形で起こっているストーリーをステージに投影していくっていう作業になるから、そこは大変でした。それでもあのクオリティーののが作れたので安心しましたし、当面の強みになると思います。よし、毎年できるな！と</p><p>来年はしたかった2度目の「BMSG FES来年はどういう形にしようかなあ。既に企画自体は具体的なものがあるので楽しみにしていてください。BMSG FESは、どこか特定のチームの集客力に依存せず、全体のお客さんが来れている状況を作る必要があるので、もし会社として信用を得て使えるとしても、ドーム規模での公演はまだタイミングではなさそうです。自社フェスなのにオーバーキャパに感じてしまうアーティストを作るのは、もう健康的じゃないと思うからです。</p><p>来れる人を増やしたいのは確かなので、アリーナ規模でも、ものすごくタイトにして、昼夜2公演でやってもいいかもしれない。その場合、フェスでしか見られないコラボを中心にして、1アーティストのオリジナルは1~2曲ずつにし、2時間くらいノンストップで見せるとか。ずっとクライマックスって感じでスピード感もあるし、悪くないかもなあ。</p><p>もちろん、様々なキャパシティーが成長するタイミングが出てきたりすれば、BMSG FES自体の在り方が変わると思いますが、少なくとも来年は、今の「皆でやる」ファミリーコンサートのスタイルを継続しようと思っています。</p>',31)])])}const d=p(o,[["render",n]]);export{_ as __pageData,d as default};
